import { fraction } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'

/* ==========================================================================
   Ekuazio-sistemak · Batxilergoa 1 · Zientziak — diagnostic, guided
   practice, exercise bank and challenges, with the scope of unit 3 of
   Santillana 1.º Bachillerato Ciencias and the systems part of unit 3 of
   Anaya Matemáticas I (all the exercises and numbers are our own). Every
   closed answer is a single number: one unknown, a sum of unknowns, the
   value of a parameter, how many solutions or integer points there are.
   An impossible row is written with its letters (0z = 5), never 0 = 5.
   ========================================================================== */

/** Arabic writes the decimal point instead of the comma, so {,} becomes . there */
const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
/** Same formula everywhere, decimal point in Arabic */
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })
const n = (value: number) => fraction(value)

/** A prompt followed by what to give */
const with_ = (prompt: LocalizedText, ...rules: LocalizedText[]): LocalizedText => ({
    eu: [prompt.eu, ...rules.map((rule) => rule.eu)].join(' '),
    es: [prompt.es, ...rules.map((rule) => rule.es)].join(' '),
    en: [prompt.en, ...rules.map((rule) => rule.en)].join(' '),
    ar: [prompt.ar, ...rules.map((rule) => rule.ar)].join(' ')
})
const solve = (formula: string) => say(`Ebatzi ${formula}.`, `Resuelve ${formula}.`, `حُلّ ${formula}.`, `Solve ${formula}.`)
const gauss = (formula: string) => say(`Ebatzi Gaussen metodoaz ${formula}.`, `Resuelve por Gauss ${formula}.`, `حُلّ بطريقة غاوس ${formula}.`, `Solve by Gaussian elimination ${formula}.`)
/** «Give the value of …» for one unknown or expression */
const give = (formula: string) => say(`Eman ${formula} balioa.`, `Da el valor de ${formula}.`, `اكتب قيمة ${formula}.`, `Give the value of ${formula}.`)
const LARGEST_X = say('Eman $x$ ezezagunaren baliorik handiena.', 'Da el mayor valor de $x$.', 'اكتب أكبر قيمة لـ $x$.', 'Give the largest value of $x$.')
const HOW_MANY = say('Zenbat soluzio ditu?', '¿Cuántas soluciones tiene?', 'كم حلًّا له؟', 'How many solutions does it have?')
/** «How many points with integer coordinates are there in the region …?» */
const latticeCount = (formula: string) => say(`Zenbat puntu oso daude ${formula} eskualdean?`, `¿Cuántos puntos de coordenadas enteras hay en la región ${formula}?`, `كم نقطة إحداثياتها صحيحة في المنطقة ${formula}؟`, `How many points with integer coordinates are there in the region ${formula}?`)

